using Clary.Api.Identity;
using Clary.Api;
using Npgsql;
using Xunit;
public class InventoryIntegrationTests {
 [Fact] public async Task RecordsValidatePersistAndRejectStaleEdits(){
  var connection=Environment.GetEnvironmentVariable("CLARY_TEST_CONNECTION")!;var schema="inventory_test_"+Guid.NewGuid().ToString("N");await using var admin=NpgsqlDataSource.Create(connection);await using(var q=admin.CreateCommand($"CREATE SCHEMA {schema}"))await q.ExecuteNonQueryAsync();
  try{await using var db=NpgsqlDataSource.Create(new NpgsqlConnectionStringBuilder(connection){SearchPath=schema+",public"}.ConnectionString);await using(var q=db.CreateCommand(await File.ReadAllTextAsync(Path.Combine(AppContext.BaseDirectory,"database","001-initial.sql"))))await q.ExecuteNonQueryAsync();await FixtureCompany.MigrateAsync(db);
   var departments=new InventoryDepartments(db);var department=await departments.SaveAsync(FixtureCompany.Context," Accounting ","#22C55E",false,default);Assert.Equal("Accounting",department.Name);Assert.Equal("#22c55e",department.Color);await Assert.ThrowsAsync<InventoryConflict>(()=>departments.SaveAsync(FixtureCompany.Context,"accounting","#123456",false,default));await Assert.ThrowsAsync<ArgumentException>(()=>departments.SaveAsync(FixtureCompany.Context,"Bad","red",false,default));await departments.SaveAsync(FixtureCompany.Context,"Accounting","#3B82F6",true,default);Assert.Equal("#3b82f6",Assert.Single(await departments.ListAsync(FixtureCompany.Context,default)).Color);var repo=new InventoryRepository(db);var dirs=new Clary.Api.Directories.DirectoryRepository(db);var it=await dirs.SaveDepartmentAsync(FixtureCompany.Context,null,new("IT","#123456"),default);var finance=await dirs.SaveDepartmentAsync(FixtureCompany.Context,null,new("Finance","#654321"),default);var jane=await dirs.SaveEmployeeAsync(FixtureCompany.Context,null,new("Jane"),default);var hq=await dirs.SaveLocationAsync(FixtureCompany.Context,null,new("HQ"),default);var input=new AssetInput(" PC-01 ","Workstation","SN1","2001:db8::1",Status:"Assigned",EmployeeId:jane.Id,DepartmentId:it.Id,LocationId:hq.Id);input=input with{CustomCategory=" Laptop "};var a=await repo.CreateAsync(FixtureCompany.Context,input,default);Assert.Equal("Laptop",a.CustomCategory);Assert.Equal("Not checked",a.SoftwareStatus);Assert.Null(a.LastSeen);Assert.Equal("IT",a.Department);
   Assert.Equal("Laptop",(await new InventoryRepository(db).GetAsync(FixtureCompany.Context,a.Id,default))!.CustomCategory);Assert.Equal(a.Id,Assert.Single(await new InventoryRepository(db).ListAsync(FixtureCompany.Context,default)).Id);await Assert.ThrowsAsync<InventoryConflict>(()=>repo.CreateAsync(FixtureCompany.Context,input with{AssetTag="pc-01"},default));await Assert.ThrowsAsync<ArgumentException>(()=>repo.CreateAsync(FixtureCompany.Context,input with{AssetTag="PC02",IpAddress="bad"},default));await Assert.ThrowsAsync<ArgumentException>(()=>repo.CreateAsync(FixtureCompany.Context,input with{Status="healthy"},default));
   var edited=await repo.UpdateAsync(FixtureCompany.Context,a.Id,input with{DepartmentId=finance.Id,CustomCategory="Workstation",Revision=a.Revision},default);Assert.Equal(2,edited.Revision);Assert.Equal("Workstation",edited.CustomCategory);Assert.Equal("Finance",edited.Department);await Assert.ThrowsAsync<InventoryConflict>(()=>repo.UpdateAsync(FixtureCompany.Context,a.Id,input with{Revision=a.Revision},default));Assert.Equal(2,(await repo.ActivityAsync(FixtureCompany.Context,10,default)).Count);Assert.Null(await repo.GetAsync(FixtureCompany.Context,Guid.NewGuid(),default));
   await Assert.ThrowsAsync<ArgumentException>(()=>repo.CreateAsync(FixtureCompany.Context,input with{AssetTag="X",Category="Unknown"},default));
   await Assert.ThrowsAsync<ArgumentException>(()=>repo.CreateAsync(FixtureCompany.Context,input with{AssetTag=new string('X',101)},default));
   await Assert.ThrowsAsync<InventoryMissing>(()=>repo.UpdateAsync(FixtureCompany.Context,Guid.NewGuid(),input with{Revision=1},default));
   await Assert.ThrowsAsync<ArgumentException>(()=>repo.CreateAsync(FixtureCompany.Context,input with{CustomCategory=new string('X',101)},default));
   foreach(var category in new[]{"Printer","Monitor","Network","Accessory"}){var item=await repo.CreateAsync(FixtureCompany.Context,input with{AssetTag=category,Category=category,IpAddress="192.168.1.5"},default);Assert.Equal(category,item.Category);}
   await using(var count=db.CreateCommand("SELECT count(*) FROM inventory_documentation"))Assert.Equal(5L,await count.ExecuteScalarAsync());await using(var count=db.CreateCommand("SELECT count(*) FROM library_folders WHERE parent_id IS NULL AND name='Inventory'"))Assert.Equal(1L,await count.ExecuteScalarAsync());await repo.CreateAsync(FixtureCompany.Context,input with{AssetTag="PRN-SECOND",Category="Printer"},default);await using(var count=db.CreateCommand("SELECT count(*) FROM inventory_documentation"))Assert.Equal(5L,await count.ExecuteScalarAsync());var printerDoc=(await new InventoryDocumentation(db).GetAsync(FixtureCompany.Context,default,"Printer")).DocumentId;Assert.NotNull(printerDoc);Assert.Contains("Printer",(await new LibraryOperations(db).ContentAsync(FixtureCompany.Context,printerDoc!.Value,default))!);
   var competing=await Task.WhenAll(Enumerable.Range(0,2).Select(async i=>{try{await repo.UpdateAsync(FixtureCompany.Context,a.Id,input with{Revision=edited.Revision,Computer="Concurrent"+i},default);return true;}catch(InventoryConflict){return false;}}));Assert.Single(competing.Where(x=>x));

  }finally{await using var q=admin.CreateCommand($"DROP SCHEMA {schema} CASCADE");await q.ExecuteNonQueryAsync();}
 }
}


